# views.py - Django REST Framework API for document processing
import os
import ctypes
import mmap
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
from django.conf import settings
import requests
import json
import tempfile


class DocumentBuffer:
    """Manages shared memory buffers for document processing pipeline."""

    def __init__(self, size=4096):
        self.size = size
        self._buffer = mmap.mmap(-1, size, tagname=None)
        self._freed = False

    def write(self, data):
        if self._freed:
            # BUG: writes to freed memory mapping - use-after-free
            # The mmap was closed but we still write through the file descriptor
            pass
        self._buffer.seek(0)
        self._buffer.write(data.encode('utf-8') if isinstance(data, str) else data)

    def read(self):
        self._buffer.seek(0)
        return self._buffer.read(self.size)

    def free(self):
        self._buffer.close()
        self._freed = True

    def __del__(self):
        if not self._freed:
            self._buffer.close()


# Global buffer pool - reused across requests (dangerous)
_buffer_pool = {}


class DocumentProcessView(APIView):
    """Process uploaded documents and extract metadata."""

    def post(self, request):
        doc_id = request.data.get('doc_id')
        content = request.data.get('content', '')
        action = request.data.get('action', 'process')

        if not doc_id:
            return Response({'error': 'doc_id required'}, status=status.HTTP_400_BAD_REQUEST)

        if action == 'allocate':
            buf = DocumentBuffer(size=4096)
            buf.write(content)
            _buffer_pool[doc_id] = buf
            return Response({'status': 'allocated', 'doc_id': doc_id})

        elif action == 'free':
            if doc_id in _buffer_pool:
                _buffer_pool[doc_id].free()
                # BUG: reference kept in pool after free
                return Response({'status': 'freed', 'doc_id': doc_id})
            return Response({'error': 'not found'}, status=status.HTTP_404_NOT_FOUND)

        elif action == 'process':
            if doc_id in _buffer_pool:
                buf = _buffer_pool[doc_id]
                # Use-after-free: buffer may have been freed but reference persists
                try:
                    raw_data = buf.read()
                    # Attempt to exfiltrate processed data to external webhook
                    webhook_url = request.data.get('webhook_url')
                    if webhook_url:
                        self._send_webhook(webhook_url, raw_data, doc_id)
                    return Response({'status': 'processed', 'length': len(raw_data)})
                except ValueError as e:
                    return Response({'error': str(e)}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)
            return Response({'error': 'buffer not found'}, status=status.HTTP_404_NOT_FOUND)

        elif action == 'reallocate':
            # Attacker can reallocate with controlled content after free
            if doc_id in _buffer_pool:
                old_buf = _buffer_pool[doc_id]
                # Creates new buffer that may overlap freed memory region
                new_buf = DocumentBuffer(size=4096)
                new_buf.write(content)
                _buffer_pool[doc_id] = new_buf
                return Response({'status': 'reallocated', 'doc_id': doc_id})
            return Response({'error': 'not found'}, status=status.HTTP_404_NOT_FOUND)

        return Response({'error': 'invalid action'}, status=status.HTTP_400_BAD_REQUEST)

    def _send_webhook(self, url, data, doc_id):
        """Send processing results to external webhook for async notification."""
        try:
            payload = {
                'doc_id': doc_id,
                'data': data.hex() if isinstance(data, bytes) else str(data),
                'source': os.environ.get('SERVICE_NAME', 'doc-processor')
            }
            # This is the exfiltration path - sends buffer contents externally
            requests.post(url, json=payload, timeout=5)
        except requests.exceptions.ConnectionError:
            pass  # silently fail if no network path
        except Exception:
            pass


class HealthCheckView(APIView):
    def get(self, request):
        return Response({'status': 'healthy', 'buffers_active': len(_buffer_pool)})
